1	function [MRSCont] = OspreyFit(MRSCont)
2	%% [MRSCont] = OspreyFit(MRSCont)
3	%   This function performs spectral fitting on MRS data loaded previously
4	%   using OspreyLoad.
5	%
6	%   The method of fit, fitting range, included metabolites and other
7	%   settings are set in the job file.
8	%
9	%   USAGE:
10	%       MRSCont = OspreyFit(MRSCont);
11	%
12	%   INPUTS:
13	%       MRSCont     = Osprey MRS data container.
14	%
15	%   OUTPUTS:
16	%       MRSCont     = Osprey MRS data container.
17	%
18	%   AUTHOR:
19	%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-02-24)
20	%       goeltzs1@jhmi.edu
21	%
22	%   CREDITS:
23	%       This code is based on numerous functions from the FID-A toolbox by
24	%       Dr. Jamie Near (McGill University)
25	%       https://github.com/CIC-methods/FID-A
26	%       Simpson et al., Magn Reson Med 77:23-33 (2017)
27	%
28	%   HISTORY:
29	%       2019-02-24: First version of the code.
30	
31	outputFolder = MRSCont.outputFolder;
32	diary(fullfile(outputFolder, 'LogFile.txt'));
33	
34	if MRSCont.flags.isGUI
35	    progressText = MRSCont.flags.inProgress;
36	else
37	    progressText = '';
38	end
39	
40	% ----- Load fit settings and fit the metabolite data -----
41	% Checking for version, toolbox, and previously run modules
42	[~,MRSCont.ver.CheckOsp ] = osp_CheckRunPreviousModule(MRSCont, 'OspreyFit');
43	% Start timer
44	MRSCont.runtime.Fit = 0;
45	
46	% Initialise the fit - this step includes:
47	% - Parse the correct basis set
48	% - Apply settings on which metabolites/MM/lipids to include in the fit
49	% - Check for inconsistencies between basis set and data
50	[MRSCont] = osp_fitInitialise(MRSCont);
51	%MRSCont.opts.fit.outputFolder = outputFolder;
52	
53	% Call the fit functions (depending on sequence type)
54	if ~MRSCont.flags.isPRIAM && ~MRSCont.flags.isMRSI
55	    if MRSCont.flags.isUnEdited
56	        [MRSCont] = osp_fitUnEdited(MRSCont);
57	    elseif MRSCont.flags.isMEGA
58	        [MRSCont] = osp_fitMEGA(MRSCont);
59	    elseif MRSCont.flags.isHERMES
60	        [MRSCont] = osp_fitHERMES(MRSCont);
61	    elseif MRSCont.flags.isHERCULES
62	        % For now, fit HERCULES like HERMES data
63	        [MRSCont] = osp_fitHERCULES(MRSCont);
64	    else
65	        msg = 'No flag set for sequence type!';
66	        fprintf(msg);
67	        error(msg);
68	    end
69	else
70	    [MRSCont] = osp_fitMultiVoxel(MRSCont);
71	end
72	
73	
74	% ----- Perform water reference and short-TE water fit -----
75	% The water signal is automatically integrated when the LCModel fit option is
76	% being used. In Osprey, we explicitly model the water data with a
77	% dedicated simulated water basis function.
78	if strcmpi(MRSCont.opts.fit.method, 'Osprey')
79	
80	    % If water reference exists, fit it
81	    if MRSCont.flags.hasRef
82	        refFitTime = tic;
83	        % Loop over all the datasets here
84	        for kk = 1:MRSCont.nDatasets
85	            [~] = printLog('OspreyFitRef',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
86	            if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.ref.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
87	                [MRSCont] = osp_fitWater(MRSCont, kk, 'ref');
88	            end
89	        end
90	        time = toc(refFitTime);
91	        if MRSCont.flags.isGUI
92	            set(progressText,'String' ,sprintf('... done.\n Elapsed time %f seconds',time));
93	            pause(1);
94	        end
95	        fprintf('... done.\n Elapsed time %f seconds\n',time);
96	        MRSCont.runtime.FitRef = time;
97	        MRSCont.runtime.Fit = MRSCont.runtime.Fit + time;
98	    end
99	
100	    % If short TE water reference exists, fit it
101	    if MRSCont.flags.hasWater
102	        waterFitTime = tic;
103	        % Loop over all the datasets here
104	        for kk = 1:MRSCont.nDatasets
105	            [~] = printLog('OspreyFitWater',kk,1,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
106	            if ~(MRSCont.flags.didFit == 1 && MRSCont.flags.speedUp && isfield(MRSCont, 'fit') && (kk > length(MRSCont.fit.results.w.fitParams))) || ~strcmp(MRSCont.ver.Osp,MRSCont.ver.CheckOsp)
107	                [MRSCont] = osp_fitWater(MRSCont, kk, 'w');
108	            end
109	        end
110	        time = toc(waterFitTime);
111	        fprintf('... done.\n Elapsed time %f seconds\n',time);
112	        MRSCont.runtime.FitWater = time;
113	        MRSCont.runtime.Fit = MRSCont.runtime.Fit + time;
114	    end
115	
116	    MRSCont.runtime.Fit = MRSCont.runtime.Fit + MRSCont.runtime.FitMet;
117	
118	else
119	    MRSCont.runtime.Fit =  MRSCont.runtime.FitMet;
120	end
121	[~] = printLog('Fulldone',MRSCont.runtime.Fit,MRSCont.nDatasets,progressText,MRSCont.flags.isGUI ,MRSCont.flags.isMRSI);
