170	            MRSCont.QM.tables.relRessum = relRessum;
171	            MRSCont.QM.tables.relResdiff1 = relResdiff1;
172	        end
173	    elseif MRSCont.flags.isHERMES
174	            relRessum = MRSCont.QM.relAmpl.metab_sum';
175	            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
176	            relResdiff2 = MRSCont.QM.relAmpl.metab_diff2';
177	            MRSCont.QM.tables.relRessum = relRessum;
178	            MRSCont.QM.tables.relResdiff1 = relResdiff1;
179	            MRSCont.QM.tables.relResdiff2 = relResdiff2;
180	    elseif MRSCont.flags.isHERCULES
181	        % For now, process HERCULES like HERMES data
182	            relRessum = MRSCont.QM.relAmpl.metab_sum';
183	            relResdiff1 = MRSCont.QM.relAmpl.metab_diff1';
184	            relResdiff2 = MRSCont.QM.relAmpl.metab_diff2';
185	            MRSCont.QM.tables.relRessum = relRessum;
186	            MRSCont.QM.tables.relResdiff1 = relResdiff1;
187	            MRSCont.QM.tables.relResdiff2 = relResdiff2;
188	    else
189	        msg = 'No flag set for sequence type!';
