191	        error(msg);
192	    end
193	
194	    % Loop over field names to populate descriptive fields of table for JSON export
195	    for JJ = L:length(MRSCont.QM.tables.Properties.VariableNames)
196	        switch MRSCont.QM.tables.Properties.VariableNames{JJ}
