199	                MRSCont.QM.tables.Properties.VariableDescriptions{'relResA'} = 'Fit quality number for spectrum A relative amplitude of the residual compared to the standard deveiation of the noise';
200	                MRSCont.QM.tables.Properties.VariableUnits{'relResA'} = 'arbitrary';
201	            case 'relRessum'
