211	                MRSCont.QM.tables.Properties.VariableDescriptions{'relResdiff2'} = 'Fit quality number for diff2 spectrum relative amplitude of the residual compared to the standard deveiation of the noise';
212	                MRSCont.QM.tables.Properties.VariableUnits{'relResdiff2'} = 'arbitrary';
213	        end
214	    end
215	
216	    %Output as .tsv
217	    osp_WriteBIDsTable(MRSCont.QM.tables, [outputFolder filesep 'QM_processed_spectra'])
218	end
219	
220	%% Clean up and save
