% Recompute quantH2O for records c and d with correct (seconds) units
function val = h2o(met, ref, metTR, metTE, watTR, watTE, T1W, T2W, T1M, T2M, extra_scale)
  % TR/TE already in SECONDS
  T1F = (1-exp(-watTR/T1W)) / (1-exp(-metTR/T1M));
  T2F = exp(-watTE/T2W) / exp(-metTE/T2M);
  val = (met/ref) * 55500 * 0.65 * T1F * T2F * extra_scale;
end
