  cbug = h2o(1, 1, 1.37e-3, 0.061e-3, 2.41e-3, 0.019e-3, T1W, T2W, T1M, T2M);
  dbug = h2o(1.64945, 1, 4.2e-3, 0.039e-3, 2.6e-3, 0.009e-3, T1W, T2W, T1M, T2M);
  disp(['bug(ms) c = ' num2str(cbug,10)]);
  disp(['bug(ms) d = ' num2str(dbug,10)]);
  disp(['bug ratio c/d = ' num2str(cbug/dbug,10)]);
end
function val = h2o(met, ref, metTR, metTE, watTR, watTE, T1W, T2W, T1M, T2M)
  T1F = (1-exp(-watTR/T1W)) / (1-exp(-metTR/T1M));
  T2F = exp(-watTE/T2W) / exp(-metTE/T2M);
  val = (met/ref) * 55500 * 0.65 * T1F * T2F;
end
