function basis = mkBasis(d)
  basis = struct();
  basis.t = d.time;
  basis.fids = d.fids;
  basis.specs = d.specs;
  basis.ppm = d.ppm;
  basis.sz = size(d.fids);
  basis.spectralwidth = d.spectral_width(1);
  basis.Bo = d.field_strength(1);
  basis.centerFreq = d.center_ppm(1);
  basis.n = d.points(1);
  basis.name = d.component_names;
  basis.nMets = d.n_metabolites(1);
  basis.nMM = d.n_macromolecules(1);
end

