input.command:
cd /workspace/task
# Reproduce reproduce.py's exact addpath + shim setup to run the real OspreyFit
mkdir -p /tmp/ver
cp /tmp/fshims/*.m /tmp/ver/
cat > /tmp/ver/ver.m <<'EOF'
function ver()
root = '/workspace/task/';
addpath([root 'source/fit']);
addpath([root 'source/libraries/FID-A/fitTools/fitModels/Osprey']);
addpath([root 'source/libraries/FID-A/processingTools']);
% check which osp_fitInitialise resolves
p = which('osp_fitInitialise');
fprintf('osp_fitInitialise resolves to: %s\n', p);
dA = load([root 'fixtures/study_record_a.mat']);
dB = load([root 'fixtures/study_record_b.mat']);
for r = 1:2
  if r==1, tag='MEGA'; d=dA; else, tag='HERMES'; d=dB; end
  container = mkfitCont(d);
  result = OspreyFit(container);
  rb = result.fit.resBasisSet.metab;
  fprintf('=== %s resBasisSet.metab size=%s ===\n', tag, mat2str(size(rb)));
  dppm = d.ppm(1,:); win = dppm>2.9 & dppm<3.2;
  for bi = 1:size(rb,1)
    for si = 1:size(rb,3)
      b = rb{bi,1,si};
      names = b.name;
      idxMM = find(strcmp(names,'MM09'));
      line = sprintf('  base#%d sub#%d %s', bi, si, strjoin(names,','));
      if ~isempty(idxMM), line=[line sprintf('  MM09_3ppm=%.7f', max(abs(b.specs(win,idxMM))) )]; end
      fprintf('%s\n', line);
    end
  end
end
end
EOF
cp /tmp/fshims/mkfitCont_helper.m /tmp/ver/ 2>/dev/null
# append helpers
cat >> /tmp/ver/ver.m <<'EOF'

function container = mkfitCont(d)
sequence = char(d.sequence);
basis = struct();
basis.t = d.time; basis.fids = d.fids; basis.specs = d.specs; basis.ppm = d.ppm;
basis.sz = size(d.fids);
basis.spectralwidth = double(d.spectral_width(1)); basis.dwelltime = 1/basis.spectralwidth;
basis.txfrq = double(d.field_strength(1))*42.577; basis.centerFreq = double(d.center_ppm(1));
basis.date = 'offline-checkpoint';
basis.dims = struct('t',1,'averages',0,'subSpecs',0,'coils',0);
basis.Bo = double(d.field_strength(1));
basis.averages = 1; basis.rawAverages = 1; basis.subspecs = 1; basis.rawSubspecs = 1;
basis.flags = mkFlags();
basis.n = double(d.points(1));
basis.name = d.component_names;
basis.names = d.subspectrum_names;
basis.nMets = double(d.n_metabolites(1)); basis.nMM = double(d.n_macromolecules(1));
container = struct();
container.outputFolder = '/tmp/qout';
container.outputFile = 'ignored.mat';
container.nDatasets = 1;
container.flags = struct();
